#pragma once
#include <stdint.h>

/* The compressed application, generated by tools/pack_image.py */
extern const uint8_t enosc3_blob[];
extern const uint32_t enosc3_blob_size;
extern const uint32_t enosc3_image_size;
extern const uint32_t enosc3_image_hash;

/* Same hash as tools/pack_image.py */
static inline uint32_t image_hash(const uint8_t *p, uint32_t n) {
  uint32_t h = 0x811C9DC5u;
  for (uint32_t i = 0; i < n; i++) {
    h ^= p[i];
    h *= 0x01000193u;
  }
  return h;
}
